// astChunk owns unused values and the next allocation size for one type.
// Handed-out values are never reused, even when a parse discards them.
type astChunk[T any] struct {
	free []T
	next int
}

// grow starts small and doubles up to limit. The request is always satisfied.
func (s *astChunk[T]) grow(n, initial, limit int) {
	size := s.next
	if size == 0 {
		size = initial
	}
	for size < n {
		size *= 2
	}
	s.free = make([]T, size)
	s.next = size * 2
	if s.next > limit {
		s.next = limit
	}
}

// astNew returns a new zero value from a chunk that grows from 8 to 256 values.
func astNew[T any](s *astChunk[T]) *T {
	if len(s.free) == 0 {
		s.grow(1, 8, 256)
	}
	v := &s.free[0]
	s.free = s.free[1:]
	return v
}

// astSlice returns n zero values with capacity n, so appending cannot overwrite
// another returned slice. Small-list chunks grow from 64 to 1,024 elements.
func astSlice[T any](s *astChunk[T], n int) []T {
	if n == 0 {
		return []T{} // an empty list, not nil
	}
	if n > 256 {
		return make([]T, n)
	}
	if len(s.free) < n {
		s.grow(n, 64, 1024)
	}
	v := s.free[:n:n]
	s.free = s.free[n:]
	return v
}

// tinit sets up the typed rules (called at the end of init, after the rule tables).
func tinit() {
	trules[24].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tTypeName)
		*v = TypeName{Span: Span{start, end}, Text: text}
		return v
	}
	trules[44].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tString)
		*v = String{Span: Span{start, end}, Text: text}
		return v
	}
	trules[47].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tNumber)
		*v = Number{Span: Span{start, end}, Text: text}
		return v
	}
	trules[51].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tBool)
		*v = Bool{Span: Span{start, end}, Text: text}
		return v
	}
	trules[52].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tNull)
		*v = Null{Span: Span{start, end}, Text: text}
		return v
	}
	trules[54].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tPlainName)
		*v = PlainName{Span: Span{start, end}, Text: text}
		return v
	}
	trules[56].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tQuotedName)
		*v = QuotedName{Span: Span{start, end}, Text: text}
		return v
	}
}

// tmk_Access makes a Access in an action (newStruct in the typed runtime).
func tmk_Access(c *tctx, final bool, f0 any, f1 any) any {
	a := c.p.ext.(*tslabs)
	v := astNew(&a.tAccess)
	v.Base = tAs[Expr](tpub(f0))
	v.Parts = tl0(a, f1)
	if final {
		v.Span = Span{c.start, c.end}
		return v
	}
	first, start, end := true, 0, 0
	spanOf(f0, &first, &start, &end)
	spanOf(f1, &first, &start, &end)
	return c.made(v, first, start, end)
}

