// tslabs holds the chunks the typed values of a parse are allocated from.
type tslabs struct {
	tBool          astChunk[Bool]
	tNull          astChunk[Null]
	tNumber        astChunk[Number]
	tPlainName     astChunk[PlainName]
	tQuotedName    astChunk[QuotedName]
	tString        astChunk[String]
	tTypeName      astChunk[TypeName]
	tAccess        astChunk[Access]
	tAnd           astChunk[And]
	tBinary        astChunk[Binary]
	tCallback      astChunk[Callback]
	tEmpty         astChunk[Empty]
	tFieldAccess   astChunk[FieldAccess]
	tGroup         astChunk[Group]
	tGuard         astChunk[Guard]
	tIndexAccess   astChunk[IndexAccess]
	tListLiteral   astChunk[ListLiteral]
	tMember        astChunk[Member]
	tMethodCall    astChunk[MethodCall]
	tNot           astChunk[Not]
	tObjectLiteral astChunk[ObjectLiteral]
	tOr            astChunk[Or]
	tTypeGroup     astChunk[TypeGroup]
	tTypeGuard     astChunk[TypeGuard]
	tTypeNamed     astChunk[TypeNamed]
	tTypeUnion     astChunk[TypeUnion]
	tUnary         astChunk[Unary]
	tVariable      astChunk[Variable]
	tl0Chunk       astChunk[Suffix]
	tl1Chunk       astChunk[Expr]
	tl2Chunk       astChunk[Name]
	tl3Chunk       astChunk[Argument]
	tl4Chunk       astChunk[*Member]
	tl5Chunk       astChunk[TypeExpr]
}

// ParseAST parses the input like Parse and returns the result as typed values. If the parse recovered
// from errors, the result is returned together with SyntaxErrors; an Error node where a struct or
// terminal type is expected becomes nil.
// It builds the values directly, without the nodes Parse returns.
func ParseAST(input string, unit ...Unit) (Expr, error) {
	a := &tslabs{}
	return tparse(trules[0], input, unit, a, func(v any) Expr { return tAs[Expr](tpub(v)) })
}

